const user = $('GET /{ig-user-id} (followers_count)').item.json;
const mediaResult = $input.first().json;
const mediaFailed = !!mediaResult.error && !mediaResult.data;
const media = (!mediaFailed && mediaResult.data) || [];

const since = new Date();
since.setDate(since.getDate() - 30);

const recent = media.filter((m) => new Date(m.timestamp) >= since);
const views = recent.map((m) => {
  const impressions = m.insights && m.insights.data && m.insights.data[0] && m.insights.data[0].values && m.insights.data[0].values[0];
  return impressions ? (impressions.value || 0) : 0;
});
const totalViews = views.reduce((sum, v) => sum + v, 0);

return [{
  json: {
    platform: 'instagram',
    account_id: user.id,
    account_name: user.username,
    followers_count: user.followers_count ?? null,
    views_recent_30d: recent.length ? totalViews : null,
    views_average: recent.length ? Math.round(totalViews / recent.length) : null,
    account_status: null
  }
}];
